<template>
  <div style="background-color: white; padding: 10px">
    <el-table :data="tableData" border style="width: 100%">
      <el-table-column prop="name" label="Type Name" width="200"/>
      <el-table-column prop="description" label="Type Description"/>
      <el-table-column prop="parentName" label="Parent" width="200"/>
    </el-table>
  </div>
</template>

<script setup>
import {listUsingGet2} from "../api/msdv-backend";
import {ref} from "vue";

// 表格数据
const tableData = ref([]);

//region 页面初始化
const init = async () => {
  // 从后端获取所有的微服务异味类别信息
  const res = await listUsingGet2({});
  // console.log(res.data)

  // 将信息存储到表格数据中
  res.data?.forEach(item => {
    // console.log(item)
    tableData.value.push(item);
  })
}
// 页面初始化
init();
//endregion

</script>
